const clients = $('Clients with QBO').all().map(i => i.json);
const txns = $('QBO: recent purchases').all().map(i => i.json);
const accts = $('QBO: chart of accounts').all().map(i => i.json);
const out = [];
for (let idx = 0; idx < clients.length; idx++) {
  const c = clients[idx];
  const purchases = (txns[idx]?.QueryResponse?.Purchase ?? []);
  const uncat = purchases.filter(p => (p.Line ?? []).some(l =>
    (l.AccountBasedExpenseLineDetail?.AccountRef?.name ?? '').toLowerCase().includes('uncategor')));
  if (!uncat.length) continue;
  const chart = (accts[idx]?.QueryResponse?.Account ?? []).map(a => ({ id: a.Id, name: a.Name, type: a.AccountType }));
  const compact = uncat.map(p => ({ id: p.Id, type: 'Purchase', date: p.TxnDate,
    desc: p.EntityRef?.name ?? p.PaymentType ?? '', memo: p.PrivateNote ?? '', amount: p.TotalAmt }));
  const payload = { model: 'claude-opus-4-8', max_tokens: 8000,
    system: "You are proposing QuickBooks categorizations for uncategorized transactions, for a human to approve. For each transaction propose the most likely expense/income account from the client's chart of accounts, with confidence. Never invent transactions; if unsure, use low confidence. These proposals are applied ONLY after human approval. Output only the JSON schema.",
    messages: [{ role: 'user', content: 'Client: ' + c.client_name + '\n\n--- CHART OF ACCOUNTS ---\n' + JSON.stringify(chart) + '\n\n--- UNCATEGORIZED TRANSACTIONS ---\n' + JSON.stringify(compact) }],
    output_config: { effort: 'high', format: { type: 'json_schema', schema: {"type": "object", "additionalProperties": false, "required": ["proposals"], "properties": {"proposals": {"type": "array", "items": {"type": "object", "additionalProperties": false, "required": ["txn_id", "txn_type", "date", "description", "amount", "proposed_account", "confidence"], "properties": {"txn_id": {"type": "string"}, "txn_type": {"type": "string"}, "date": {"type": ["string", "null"]}, "description": {"type": "string"}, "amount": {"type": ["number", "null"]}, "proposed_account": {"type": "string"}, "confidence": {"type": "string", "enum": ["high", "medium", "low"]}}}}}} } } };
  out.push({ json: { client_id: c.client_id, realm_id: c.qbo_realm_id, chart, payload } });
}
return out;

const srcs = $('Build request: reclass proposals').all().map(i => i.json);
const out = [];
$input.all().forEach((i, idx) => {
  const src = srcs[idx];
  const text = i.json.content?.[0]?.text ?? '{}';
  let parsed; try { parsed = JSON.parse(text); } catch (e) { parsed = { proposals: [] }; }
  for (const pr of (parsed.proposals ?? [])) {
    const acct = (src.chart ?? []).find(a => a.name.toLowerCase() === String(pr.proposed_account).toLowerCase());
    out.push({ json: { client_id: src.client_id, realm_id: src.realm_id, txn_id: pr.txn_id,
      txn_type: pr.txn_type, date: pr.date, description: pr.description, amount: pr.amount,
      proposed_account: pr.proposed_account, proposed_account_id: acct?.id ?? '',
      confidence: pr.confidence, approved: 'FALSE', applied: 'FALSE', approved_by: '' } });
  }
});
return out;
